  @override
  String aspAiInfluence(Object planet, Object targets, Object trait) {
    return '${planet} ${targets} ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰ ਰਿਹਾ ਹੈ। ਇਸ ਨਾਲ ਇਨ੍ਹਾਂ ਗ੍ਰਹਿਆਂ ਦੁਆਰਾ ਦਰਸਾਏ ਗਏ ਖੇਤਰਾਂ ਵਿੱਚ ${trait} ਆ ਸਕਦਾ ਹੈ।';
